from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1];Q=R/'reports';P=R.parents[2]/'reconstruction/CatGunnerUnityClient'
def read(n):return json.loads((Q/n).read_text())
runs=[]
for name,key,total in [('weapon-detail-playmode.json','OriginalWeaponPresentationTests',4),('weapon-detail-regression-temporary-gun.json','OriginalTemporaryGunTests',8),('weapon-detail-regression-inventory.json','OriginalInventoryTests',6),('weapon-detail-regression-startup.json','OriginalStartupTests',4),('weapon-detail-regression-star-popup.json','OriginalStarTests.OriginalSlotPopup',1)]:
 d=read(name);assert d['status']=='completed' and d['summary']['total']==d['summary']['passed']==total and d['summary']['failed']==0;assert all(key in x['FullName'] for x in d['results']);runs.append({'report':name,'filter':key,'duration':d['duration'],'summary':d['summary']})
protection=read('weapon-detail-preservation.json');assert protection['allProtectedOriginalAndProfileRecordsUnchanged']
h=read('weapon-detail-editor-handoff.json');assert not h['playing'] and not h['dirty'] and not h['compiling'] and not h['updating'] and h['persist'] and not h['saveFolderOverride'] and not h['testHostFolder'] and h['timeScale']==1 and not h['inputOverrides'] and not h['mouseFixtures'] and not h['missingScripts'] and h['runtimeWeaponTextStyles']==0 and h['originalNewGunBackgroundHidden'] and h['originalNewGunLifetimeSeconds']==2
console=read('weapon-detail-final-console.json')['data']['result'];assert not console['groundTruth']['compilationFailed'] and console['groundTruth']['consoleErrors']==0
for x in protection['sourceChanges']:
 assert hashlib.sha256(Path(x['path']).read_bytes()).hexdigest()==x['sha256']
images=[]
for n in ['explosive-info','newgun-open']:
 p=Q/'visual'/('weapon-detail-'+n+'-gpu.png');assert p.exists();images.append({'path':str(p.relative_to(R)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'actuallyViewed':True})
failures=[{'report':n,'duration':read(n)['duration'],'summary':read(n)['summary']} for n in ['weapon-detail-baseline-failure.json','weapon-detail-first-attempt.json','weapon-detail-second-attempt.json','weapon-detail-third-attempt.json','weapon-detail-fourth-attempt.json']]
e={'rule':59,'target':'com.Chodun.CatGunner 1.1.61 vc257 ARM64','scopeComplete':False,'native':read('weapon-detail-native-contract.json'),'contract':read('weapon-detail-reconstruction-contract.json'),'independentCompletedBatches':runs,'historicalFailedAttempts':failures,'intermediatePassingBatchBeforeFinalAudioAbi':{'report':'weapon-detail-pre-final-audio-playmode.json','summary':read('weapon-detail-pre-final-audio-playmode.json')['summary'],'note':'Not final code: subsequently corrected sound volume override after ARM64 ABI check; final complete batch rerun.'},'failedAttemptNotes':['Baseline enum text instead of original description','First: test wrongly assumed gun4 Explosive and acquired13grade markers; real table gun4 Shotgun and original7marker array','Second: test treated original hidden Background as modal close; original Destroy_Time2 toast corrected','Third: normal periodic LastSaveTime changed in long animation test; logical state compares all serialized gameplay fields except this timestamp','Fourth: fixture SetCleared had not been synchronized to serialized state before normal autosave; fixture SaveNow synchronizes it before snapshots'],'visual':images,'preservation':protection,'fontCacheChange':read('weapon-detail-local-font-cache-change.json'),'fontBoundary':'Existing generated StarChineseFallback glyph cache changed by TMP automatic caching; exact old asset bytes were not backed up, no byte-preservation claim for this one local cache. Original Chinese font source/meta and all scene/animation/GUID/user-profile boundaries unchanged. ClearDynamicDataOnBuild remains1; original source plus coherent runtime material/wrapping adapters.','editorHandoff':h,'finalConsole':console,'pending':['Full I2 language state/settings and remaining UI/tutorial/VFX flows','Exact InfVal presentation and full original pointer/animation/tween chains','Trusted server time/live config/SDK/account/cloud services','Player/device acceptance and human original comparison; other-language rendered fonts not accepted'],'apkBuilt':False,'gitDelivered':False};(Q/'weapon-detail-evidence.json').write_text(json.dumps(e,ensure_ascii=False,indent=2));print({'rule':59,'independentBatches':len(runs),'sceneObjects':h['objects'],'scopeComplete':False})
